div.script:
// Spinner functionality
document.addEventListener('DOMContentLoaded', function() {
  // Get the spinner element
  const spinner = document.getElementById('spinner');

  // Make sure the spinner is visible during initial page load
  if (spinner) {
    spinner.classList.add('show');
  }

  // Hide spinner when everything is fully loaded
  window.addEventListener('load', function() {
    // Small delay to ensure everything is rendered
    setTimeout(function() {
      // Remove the "show" class to trigger the CSS transition
      if (spinner) {
        spinner.classList.remove('show');
      }

      // Dispatch a custom event when spinner is hidden
      setTimeout(function() {
        // Create and dispatch custom event after spinner transition completes
        const spinnerCompleteEvent = new CustomEvent('spinnerComplete');
        document.dispatchEvent(spinnerCompleteEvent);
      }, 500); // Match the spinner transition time

    }, 800); // Slightly longer delay to appreciate the overlay
  });
});

// Carousel animations functionality (trigger first after spinner)
document.addEventListener('DOMContentLoaded', function() {
  const carousel = document.getElementById('header-carousel');
  const carouselItems = document.querySelectorAll('#header-carousel .carousel-item');

  // Function to prepare and play carousel animations
  function setupCarouselAnimations() {
    // Initially hide all animated elements by removing active class
    carouselItems.forEach(item => {
      if (item.classList.contains('active')) {
        // Temporarily remove active class
        item.classList.remove('active');
        // Mark this item to be activated later
        item.setAttribute('data-was-active', 'true');
      }
    });

    // Wait for the spinner to complete before starting carousel animations
    document.addEventListener('spinnerComplete', function() {
      // Find the item that should be active and re-add the class
      const itemToActivate = document.querySelector('#header-carousel .carousel-item[data-was-active="true"]');
      if (itemToActivate) {
        itemToActivate.classList.add('active');
      } else if (carouselItems.length > 0) {
        // If no item was marked, activate the first one
        carouselItems[0].classList.add('active');
      }

      // After carousel animation starts, dispatch event for other sections
      // The carousel animation takes about 1s to complete based on your CSS
      setTimeout(function() {
        const carouselAnimationCompleteEvent = new CustomEvent('carouselAnimationComplete');
        document.dispatchEvent(carouselAnimationCompleteEvent);
      }, 1000);
    });
  }

  // Call the setup function
  setupCarouselAnimations();
});

// Disable about section animations until carousel completes
document.addEventListener('DOMContentLoaded', function() {
  // First, hide the about section completely
  const aboutUsSection = document.querySelector('.container-xxl.about-us');

  if (aboutUsSection) {
    // Hide the entire section initially
    aboutUsSection.style.opacity = '0';
    aboutUsSection.style.transition = 'opacity 0.5s ease';

    // Only show the section after carousel animation completes
    document.addEventListener('carouselAnimationComplete', function() {
      // Fade in the section
      aboutUsSection.style.opacity = '1';
    });
  }
});

// Slide-up animation for the about-us section (wait for carousel)
document.addEventListener('DOMContentLoaded', function() {
  function initializeAboutAnimation() {
    // Specifically target the about-us section
    const aboutUsSection = document.querySelector('.container-xxl.about-us');

    if (aboutUsSection) {
      // Target the left and right sections separately
      const leftSection = aboutUsSection.querySelector('.col-lg-6:first-child');
      const rightSection = aboutUsSection.querySelector('.col-lg-6:last-child');

      // Set initial states
      // Left section starts off-screen from the bottom
      leftSection.style.opacity = '0';
      leftSection.style.transform = 'translateY(500px)';
      leftSection.style.transition = 'opacity 1.5s ease, transform 1.5s ease';

      // Right section starts invisible and below its final position
      rightSection.style.opacity = '0';
      rightSection.style.transform = 'translateY(500px)';
      rightSection.style.transition = 'opacity 2s ease, transform 2s ease';

      // Create Intersection Observer for the whole section
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          // When about-us section enters viewport
          if (entry.isIntersecting) {
            // First animate the left section sliding in
            setTimeout(() => {
              leftSection.style.opacity = '1';
              leftSection.style.transform = 'translateY(0)';

              // Then fade in and slide up the right section after the left section animation completes
              setTimeout(() => {
                rightSection.style.opacity = '1';
                rightSection.style.transform = 'translateY(0)';
              }, 1200); // Increased delay for right section
            }, 100);

            // Unobserve after animation sequence is started
            observer.unobserve(aboutUsSection);
          }
        });
      }, {
        root: null, // viewport
        threshold: 0.50, // trigger when 50% of element is visible
        rootMargin: '0px' // no margin
      });

      // Only start observing after carousel animation is complete
      document.addEventListener('carouselAnimationComplete', function() {
        // Start observing the about-us section
        observer.observe(aboutUsSection);
      });
    }
  }

  // Initialize immediately to set up the observer
  initializeAboutAnimation();
});

// Intersection Observer for triggering animations on scroll (modified)
document.addEventListener('DOMContentLoaded', function() {
  // Wait for carousel animation to complete before initializing
  function initializeFactsAnimation() {
    // Get all fact boxes
    const factBoxes = document.querySelectorAll('.facts .col-lg-4');

    // Create the Intersection Observer
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        // Add the animation class when the element is in view
        if (entry.isIntersecting) {
          entry.target.classList.add('animate-in');
          // Unobserve after animation has been triggered
          observer.unobserve(entry.target);
        }
      });
    }, {
      // Configure the observer options
      root: null, // Use the viewport as the root
      rootMargin: '0px', // No margin
      threshold: 0.1 // Trigger when at least 10% of the element is visible
    });

    // Observe all fact boxes
    factBoxes.forEach(box => {
      observer.observe(box);
    });

    // Fallback for browsers that don't support Intersection Observer
    if (!('IntersectionObserver' in window)) {
      factBoxes.forEach(box => {
        box.classList.add('animate-in');
      });
    }
  }

  // Initialize after carousel animation completes
  document.addEventListener('carouselAnimationComplete', initializeFactsAnimation);
});

// Optional: Add animation for elements entering viewport (modified)
function animateOnViewport() {
  const factBoxes = document.querySelectorAll('.facts .col-lg-4:not(.animate-in)');

  factBoxes.forEach(box => {
    const rect = box.getBoundingClientRect();
    const windowHeight = window.innerHeight || document.documentElement.clientHeight;

    if (rect.top <= windowHeight * 0.8) {
      box.classList.add('animate-in');
    }
  });
}

// Only add scroll listener after carousel animation completes
document.addEventListener('carouselAnimationComplete', function() {
  // Add scroll event listener for the fallback function
  window.addEventListener('scroll', animateOnViewport, { passive: true });
});

// Team animation (modified)
document.addEventListener('DOMContentLoaded', function() {
  function initializeTeamAnimation() {
    // Select all team items
    const teamItems = document.querySelectorAll('.team-item');
    const teamSection = document.querySelector('.team-items');

    if (!teamSection || teamItems.length === 0) {
      console.error('Team section or team items not found');
      return;
    }

    // Hide all items initially
    teamItems.forEach(item => {
      item.style.opacity = '0';
      item.style.transform = 'translateY(50px)';
      item.style.transition = 'opacity 0.8s ease-out, transform 0.8s ease-out';
    });

    // Function to animate items sequentially
    function animateItems() {
      teamItems.forEach((item, index) => {
        setTimeout(() => {
          item.style.opacity = '1';
          item.style.transform = 'translateY(0)';
        }, index * 400); // 400ms delay between each item
      });
    }

    // Create an Intersection Observer
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        // If section is visible
        if (entry.isIntersecting) {
          animateItems();
          // Stop observing after animation is triggered
          observer.unobserve(entry.target);
        }
      });
    }, {
      // Trigger when at least 50% of the section is visible
      threshold: 0.5
    });

    // Start observing the team section
    observer.observe(teamSection);
  }

  // Initialize after carousel animation completes
  document.addEventListener('carouselAnimationComplete', initializeTeamAnimation);



});
